<?php
declare(strict_types=1);
namespace App\Controller;
use App\Entity\{Appointment,AppointmentAvailability,AppointmentResource,AppointmentType,User};use App\Repository\TenantMembershipRepository;use App\Service\ActiveTenantProvider;use Doctrine\DBAL\LockMode;use Doctrine\ORM\EntityManagerInterface;use Symfony\Bundle\SecurityBundle\Security;use Symfony\Component\HttpFoundation\{JsonResponse,Request,Response};use Symfony\Component\Routing\Attribute\Route;
final class ApiAppointmentController{
 public function __construct(private readonly EntityManagerInterface $em,private readonly ActiveTenantProvider $tenant,private readonly TenantMembershipRepository $memberships,private readonly Security $security){}
 #[Route('/api/v1/appointments/types',methods:['GET'])] public function types():JsonResponse{return new JsonResponse(['types'=>array_map(fn(AppointmentType $t)=>$this->type($t),$this->em->getRepository(AppointmentType::class)->findBy(['tenant'=>$this->tenant->get(),'isVisible'=>true]))]);}
 #[Route('/api/v1/appointments/slots',methods:['GET'])] public function slots(Request $request):JsonResponse{$type=$this->typeFor((int)$request->query->get('typeId'));$date=\DateTimeImmutable::createFromFormat('!Y-m-d',(string)$request->query->get('date'));if(!$type||!$date)return new JsonResponse(['message'=>'Ungültige Auswahl.'],422);return new JsonResponse(['slots'=>$this->slotsFor($type,$date)]);}
 #[Route('/api/v1/appointments',methods:['POST'])] public function book(Request $request):JsonResponse{$user=$this->customer();if(!$user)return new JsonResponse(['message'=>'Unauthorized.'],401);$data=$request->toArray();$type=$this->typeFor((int)($data['typeId']??0));$start=isset($data['startsAt'])?new \DateTimeImmutable((string)$data['startsAt']):null;if(!$type||!$start||$start<new \DateTimeImmutable()||$start>(new \DateTimeImmutable('+14 days')))return new JsonResponse(['message'=>'Ungültiger Termin.'],422);foreach($this->slotsFor($type,$start->setTime(0,0)) as $slot){if($slot['startsAt']!==$start->format(DATE_ATOM))continue;$resource=$this->em->getRepository(AppointmentResource::class)->find($slot['resourceId']);if(!$resource)continue;return $this->em->wrapInTransaction(function()use($resource,$type,$user,$start,$data){$this->em->lock($resource,LockMode::PESSIMISTIC_WRITE);if(!$this->isFree($resource,$start,$type))return new JsonResponse(['message'=>'Dieser Slot wurde soeben vergeben.'],409);$end=$start->modify('+'.$type->getDurationMinutes().' minutes');$appointment=new Appointment($this->tenant->get(),$resource,$type,$user,$start,$end,substr(trim((string)($data['note']??'')),0,1000)?:null);$this->em->persist($appointment);$this->em->flush();return new JsonResponse(['appointment'=>$this->appointment($appointment)],201);});}return new JsonResponse(['message'=>'Termin nicht verfügbar.'],409);}
 #[Route('/api/v1/appointments/mine',methods:['GET'])] public function mine():JsonResponse{$user=$this->customer();if(!$user)return new JsonResponse(['message'=>'Unauthorized.'],401);$items=$this->em->getRepository(Appointment::class)->findBy(['customer'=>$user],['startsAt'=>'ASC']);return new JsonResponse(['appointments'=>array_map(fn(Appointment $a)=>$this->appointment($a),$items)]);}
 #[Route('/api/v1/appointments/{id}/cancel',methods:['POST'])] public function cancel(int $id):JsonResponse{$user=$this->customer();$a=$this->em->getRepository(Appointment::class)->find($id);if(!$user||!$a instanceof Appointment||$a->getCustomer()!==$user)return new JsonResponse(['message'=>'Nicht gefunden.'],404);if($a->getStartsAt()<new \DateTimeImmutable('+24 hours'))return new JsonResponse(['message'=>'Bitte kontaktieren Sie die Apotheke zur Stornierung.'],422);$a->cancel();$this->em->flush();return new JsonResponse(['appointment'=>$this->appointment($a)]);}
 #[Route('/api/v1/admin/appointments/types',methods:['GET','POST'])] public function adminTypes(Request $r):JsonResponse{if(!$this->admin())return new JsonResponse(['message'=>'Forbidden'],403);if($r->isMethod('GET'))return new JsonResponse(['types'=>array_map(fn(AppointmentType $t)=>$this->type($t),$this->em->getRepository(AppointmentType::class)->findBy(['tenant'=>$this->tenant->get()]))]);$d=$r->toArray();$duration=(int)($d['durationMinutes']??0);if(trim((string)($d['title']??''))===''||$duration<5)return new JsonResponse(['message'=>'Ungültige Terminart.'],422);$t=new AppointmentType($this->tenant->get(),trim($d['title']),trim((string)($d['description']??''))?:null,$duration,max(0,(int)($d['bufferMinutes']??5)));$this->em->persist($t);$this->em->flush();return new JsonResponse(['type'=>$this->type($t)],201);}
 #[Route('/api/v1/admin/appointments/resources',methods:['GET','POST'])] public function adminResources(Request $r):JsonResponse{if(!$this->admin())return new JsonResponse(['message'=>'Forbidden'],403);if($r->isMethod('GET'))return new JsonResponse(['resources'=>array_map(fn(AppointmentResource $x)=>['id'=>$x->getId(),'name'=>$x->getName()],$this->em->getRepository(AppointmentResource::class)->findBy(['tenant'=>$this->tenant->get(),'isActive'=>true]))]);$d=$r->toArray();if(trim((string)($d['name']??''))==='')return new JsonResponse(['message'=>'Name fehlt.'],422);$x=new AppointmentResource($this->tenant->get(),trim($d['name']));$this->em->persist($x);$this->em->flush();return new JsonResponse(['resource'=>['id'=>$x->getId(),'name'=>$x->getName()]],201);}
 #[Route('/api/v1/admin/appointments/availability',methods:['GET','POST'])] public function availability(Request $r):JsonResponse{if(!$this->admin())return new JsonResponse(['message'=>'Forbidden'],403);if($r->isMethod('GET')){$items=$this->em->getRepository(AppointmentAvailability::class)->findAll();return new JsonResponse(['availability'=>array_map(fn(AppointmentAvailability $a)=>['resourceId'=>$a->getResource()->getId(),'typeId'=>$a->getType()->getId(),'weekday'=>$a->getWeekday(),'startsAt'=>$a->getStartsAt(),'endsAt'=>$a->getEndsAt()],$items)]);} $d=$r->toArray();$resource=$this->em->getRepository(AppointmentResource::class)->find((int)($d['resourceId']??0));$type=$this->typeFor((int)($d['typeId']??0));$days=$d['weekdays']??[];if(!$resource instanceof AppointmentResource||!$type||!is_array($days)||!preg_match('/^\d\d:\d\d$/',(string)($d['startsAt']??''))||!preg_match('/^\d\d:\d\d$/',(string)($d['endsAt']??'')))return new JsonResponse(['message'=>'Ungültige Verfügbarkeit.'],422);foreach($days as $day){if(is_int($day)||ctype_digit((string)$day))$this->em->persist(new AppointmentAvailability($resource,$type,(int)$day,$d['startsAt'],$d['endsAt']));}$this->em->flush();return new JsonResponse(status:201);}
 private function slotsFor(AppointmentType $type,\DateTimeImmutable $day):array{$slots=[];$weekday=(int)$day->format('N');foreach($this->em->getRepository(AppointmentAvailability::class)->findBy(['type'=>$type,'weekday'=>$weekday]) as $rule){$resource=$rule->getResource();if(!$resource->isActive())continue;$cursor=new \DateTimeImmutable($day->format('Y-m-d').' '.$rule->getStartsAt());$limit=new \DateTimeImmutable($day->format('Y-m-d').' '.$rule->getEndsAt());while($cursor->modify('+'.$type->getDurationMinutes().' minutes')<=$limit){if($this->isFree($resource,$cursor,$type))$slots[]=['resourceId'=>$resource->getId(),'startsAt'=>$cursor->format(DATE_ATOM),'endsAt'=>$cursor->modify('+'.$type->getDurationMinutes().' minutes')->format(DATE_ATOM)];$cursor=$cursor->modify('+'.$type->getDurationMinutes().' minutes');}}usort($slots,fn($a,$b)=>$a['startsAt']<=>$b['startsAt']);return $slots;}
 private function isFree(AppointmentResource $resource,\DateTimeImmutable $start,AppointmentType $type):bool{$end=$start->modify('+'.($type->getDurationMinutes()+$type->getBufferMinutes()).' minutes');return (int)$this->em->createQuery('SELECT COUNT(a.id) FROM App\\Entity\\Appointment a WHERE a.resource=:r AND a.status=:s AND a.startsAt < :end AND a.endsAt > :start')->setParameter('r',$resource)->setParameter('s','reserved')->setParameter('start',$start)->setParameter('end',$end)->getSingleScalarResult()===0;}
 private function typeFor(int $id):?AppointmentType{$x=$this->em->getRepository(AppointmentType::class)->find($id);return $x instanceof AppointmentType&&$x->getTenant()===$this->tenant->get()?$x:null;} private function type(AppointmentType $t):array{return ['id'=>$t->getId(),'title'=>$t->getTitle(),'description'=>$t->getDescription(),'durationMinutes'=>$t->getDurationMinutes(),'bufferMinutes'=>$t->getBufferMinutes(),'isVisible'=>$t->isVisible()];} private function appointment(Appointment $a):array{return ['id'=>$a->getId(),'type'=>$a->getType()->getTitle(),'resource'=>$a->getResource()->getName(),'startsAt'=>$a->getStartsAt()->format(DATE_ATOM),'endsAt'=>$a->getEndsAt()->format(DATE_ATOM),'status'=>$a->getStatus()];} private function customer():?User{$u=$this->security->getUser();return $u instanceof User&&$this->memberships->hasActiveMembershipFor($u,$this->tenant->get())?$u:null;}private function admin():bool{$u=$this->security->getUser();if(!$u instanceof User)return false;$m=$this->memberships->findForUserAndTenant($u,$this->tenant->get());return $m&&[]!==array_intersect(['ROLE_TENANT_STAFF','ROLE_TENANT_ADMIN'],$m->getRoles());}}
